package com.keyforge.nativeload;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class NativeWorkgroupMembershipParserTest {@Test void retainsPageCursorEvenWhenRelationshipRowsAreEmpty(){var p=new NativeWorkgroupMembershipParser().parse("{\"nextStart\":100,\"done\":false,\"rows\":[]}");assertEquals(100,p.nextStart);assertFalse(p.done);assertTrue(p.rows.isEmpty());}@Test void parsesNativeEdge(){var p=new NativeWorkgroupMembershipParser().parse("{\"nextStart\":3,\"done\":true,\"rows\":[{\"workgroupId\":\"11111111111111111111111111111111\",\"identityId\":\"22222222222222222222222222222222\",\"identityName\":\"A\"}]}");assertEquals("A",p.rows.get(0).identityName);}@Test void rejectsMalformedContract(){assertThrows(NativeImportException.class,()->new NativeWorkgroupMembershipParser().parse("{\"rows\":[]}"));}}
